describe('Login with Email or Username Interchangeability', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should successfully log in using email address', () => {
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('SecurePassword123!');
    cy.get('[data-testid="login-button"]').click();
    cy.intercept('POST', '/api/auth/login').as('loginRequest');
    cy.wait('@loginRequest');
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="welcome-message"]').should('be.visible');
    cy.get('[data-testid="welcome-message"]').should('contain', 'Welcome');
  });

  it('should successfully log in using username', () => {
    cy.get('[data-testid="username-input"]').type('john.doe');
    cy.get('[data-testid="password-input"]').type('SecurePassword123!');
    cy.get('[data-testid="login-button"]').click();
    cy.intercept('POST', '/api/auth/login').as('loginRequest');
    cy.wait('@loginRequest');
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="welcome-message"]').should('be.visible');
    cy.get('[data-testid="welcome-message"]').should('contain', 'Welcome');
  });

  it('should display error when login fails with invalid credentials', () => {
    cy.get('[data-testid="email-input"]').type('invalid@example.com');
    cy.get('[data-testid="password-input"]').type('WrongPassword123!');
    cy.get('[data-testid="login-button"]').click();
    cy.intercept('POST', '/api/auth/login', {
      statusCode: 401,
      body: { error: 'Invalid credentials' }
    }).as('loginRequest');
    cy.wait('@loginRequest');
    cy.url().should('eq', '/login');
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid credentials');
  });

  it('should handle empty email/username field and prevent login', () => {
    cy.get('[data-testid="password-input"]').type('SecurePassword123!');
    cy.get('[data-testid="login-button"]').click();
    cy.intercept('POST', '/api/auth/login', {
      statusCode: 400,
      body: { error: 'Email or username is required' }
    }).as('loginRequest');
    cy.wait('@loginRequest');
    cy.url().should('eq', '/login');
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Email or username is required');
  });
});
